 terminalPosition(reference){const separator=reference.lastIndexOf(':'),component=this.schematic.getComponent(reference.slice(0,separator)),terminal=reference.slice(separator+1);if(!component)return null;let local={x:0,y:0};if(component.type==='transformer'){const grid=this.schematic.grid.snapGrid,half=component.heightCells/2*grid.stepY;local.x=(terminal.startsWith('P')?-2:2)*grid.stepX;local.y={P1:-half,P2:half,S1:-half,S2:0,S3:half}[terminal]??0}else if(component.type==='contact'&&component.contactType==='CHANGEOVER'){const grid=this.schematic.grid.snapGrid,vertical=component.rotation%180!==0,localStepX=vertical?grid.stepY:grid.stepX,localStepY=vertical?grid.stepX:grid.stepY,mirror=component.mirrored?-1:1;local.x=(terminal==='COM'?-2:2)*localStepX;local.y=terminal==='NC'?-localStepY*mirror:terminal==='NO'?localStepY*mirror:0}else if(component.type!=='junction')local.x=terminal==='A'||terminal==='OUT'?-50:50;const angle=component.rotation*Math.PI/180,cos=Math.cos(angle),sin=Math.sin(angle);return{x:Math.round(component.position.x+local.x*cos-local.y*sin),y:Math.round(component.position.y+local.x*sin+local.y*cos)}}
 segmentOrientation(a,b){return Math.abs(b.x-a.x)>=Math.abs(b.y-a.y)?'H':'V'}
 moveWireEndpoint(wire,atStart,point){const index=atStart?0:wire.points.length-1,neighborIndex=atStart?1:wire.points.length-2,old=wire.points[index],neighbor=wire.points[neighborIndex],orientation=this.segmentOrientation(old,neighbor);if(wire.points.length===2){const other={...neighbor},bend=orientation==='H'?{x:other.x,y:point.y}:{x:point.x,y:other.y};wire.points=atStart?[point,bend,other]:[other,bend,point];return}wire.points[index]=point;if(orientation==='H')wire.points[neighborIndex].y=point.y;else wire.points[neighborIndex].x=point.x}
 syncConnectedWires(component){if(!component)return;for(const wire of this.schematic.wires){if(wire.from?.startsWith(`${component.id}:`)&&wire.points.length){const point=this.terminalPosition(wire.from);if(point)this.moveWireEndpoint(wire,true,point)}if(wire.to?.startsWith(`${component.id}:`)&&wire.points.length){const point=this.terminalPosition(wire.to);if(point)this.moveWireEndpoint(wire,false,point)}}}
 moveWirePoint(drag,point){const wire=this.schematic.getWire(drag.wireId),source=drag.originalPoints,index=drag.index;if(!wire||index<=0||index>=source.length-1)return;const prefix=source.slice(0,index).map(p=>({...p})),suffix=source.slice(index+1).map(p=>({...p})),previous=prefix.at(-1),next=suffix[0],before=drag.previousOrientation==='H'?{x:point.x,y:previous.y}:{x:previous.x,y:point.y},after=drag.nextOrientation==='H'?{x:next.x,y:point.y}:{x:point.x,y:next.y},same=(a,b)=>a.x===b.x&&a.y===b.y;const points=[...prefix];if(!same(before,previous)&&!same(before,point))points.push(before);const selectedIndex=points.length;points.push(point);if(!same(after,point)&&!same(after,next))points.push(after);wire.points=[...points,...suffix];this.selectedWirePoint=selectedIndex}
 deleteSelectedWirePoint(){const wire=this.schematic.getWire(this.selection),index=this.selectedWirePoint;if(!wire||index===null||index<=0||index>=wire.points.length-1)return false;this.snapshot();const previous=wire.points[index-1],next=wire.points[index+1];if(previous.x===next.x||previous.y===next.y)wire.points.splice(index,1);else wire.points.splice(index,1,{x:next.x,y:previous.y});this.selectedWirePoint=null;this.onChange('delete-wire-point');this.render();return true}
