 key(e,down){const target=e.target||document.activeElement,editing=['INPUT','TEXTAREA','SELECT'].includes(target?.tagName)||target?.isContentEditable;if(e.code==='Space'){if(!down)this.space=false;else if(!editing){this.space=true;e.preventDefault()}}if(!down||editing)return;if(e.key==='Escape'){e.preventDefault();if(this.escapeArmed){this.onCancel?.();this.onStatus(null,'Mode sélection');this.escapeArmed=false}else{this.cancelAction(false);this.escapeArmed=true}return}this.escapeArmed=false;if(e.key==='Delete'&&this.selectedWirePoint!==null){this.deleteSelectedWirePoint();return}if(e.key==='Delete'&&this.selections.size)this.remove();if(e.key.toLowerCase()==='r'&&this.selection)this.rotate();if(e.ctrlKey&&e.key.toLowerCase()==='z'){e.preventDefault();this.undo()}if(e.ctrlKey&&(e.key.toLowerCase()==='y'||e.shiftKey&&e.key.toLowerCase()==='z')){e.preventDefault();this.redo()}if(e.ctrlKey&&e.key.toLowerCase()==='d'){e.preventDefault();this.duplicate()}}
